/** Failure raised while parsing or expanding a template. */
export class UriTemplateError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the `{` that opens the offending expression
   */
  constructor(message, index) {
    super(message);
    this.name = 'UriTemplateError';
    this.index = index;
  }
}

const RESERVED_OPERATORS = new Set(['=', ',', '!', '@', '|']);
const OPERATORS = new Set(['+', '#', '.', '/', ';', '?', '&']);

const SEGMENT = '(?:[A-Za-z0-9_]|%[0-9A-Fa-f]{2})+';
const NAME_RE = new RegExp(`^${SEGMENT}(?:\\.${SEGMENT})*$`);
const MAX_LENGTH_RE = /^[1-9][0-9]{0,3}$/;

function isValidName(name) {
  return NAME_RE.test(name);
}

function parseVarSpec(spec, exprStart) {
  let explode = false;
  let maxLength = null;
  let namePart = spec;

  if (spec.endsWith('*')) {
    explode = true;
    namePart = spec.slice(0, -1);
  } else {
    const colonIndex = spec.indexOf(':');
    if (colonIndex !== -1) {
      namePart = spec.slice(0, colonIndex);
      const modifier = spec.slice(colonIndex);
      const digits = modifier.slice(1);
      if (!MAX_LENGTH_RE.test(digits)) {
        throw new UriTemplateError(`invalid prefix modifier '${modifier}' at ${exprStart}`, exprStart);
      }
      maxLength = Number(digits);
    }
  }

  if (!isValidName(namePart)) {
    throw new UriTemplateError(`invalid variable name '${namePart}' at ${exprStart}`, exprStart);
  }

  return { name: namePart, explode, maxLength };
}

/**
 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');

  const parts = [];
  let literal = '';
  let i = 0;
  const n = template.length;

  while (i < n) {
    const ch = template[i];

    if (ch === '}') {
      throw new UriTemplateError(`unexpected '}' at ${i}`, i);
    }

    if (ch === '{') {
      if (literal !== '') {
        parts.push({ type: 'literal', value: literal });
        literal = '';
      }

      const start = i;
      const end = template.indexOf('}', start + 1);
      if (end === -1) throw new UriTemplateError(`unterminated expression at ${start}`, start);

      const content = template.slice(start + 1, end);
      if (content === '') throw new UriTemplateError(`empty expression at ${start}`, start);

      let operator = '';
      let rest = content;
      const first = content[0];

      if (RESERVED_OPERATORS.has(first)) {
        throw new UriTemplateError(`reserved operator '${first}' at ${start}`, start);
      }

      if (OPERATORS.has(first)) {
        operator = first;
        rest = content.slice(1);
      }

      const specs = rest.split(',');
      const variables = specs.map((spec) => {
        if (spec === '') throw new UriTemplateError(`empty variable specification at ${start}`, start);
        return parseVarSpec(spec, start);
      });

      parts.push({ type: 'expression', operator, variables });
      i = end + 1;
      continue;
    }

    literal += ch;
    i += 1;
  }

  if (literal !== '') parts.push({ type: 'literal', value: literal });

  return parts;
}
"}

